-- TEST ONLY: no provider calls; queue preparation is scoped to a disposable event.
-- Everything, including release-date adjustment and notification jobs, rolls back.
begin;
create function pg_temp.thanks_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if;end;$$;
create function pg_temp.thanks_denied(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end;$$;
insert into auth.users(id,email,aud,role,raw_app_meta_data,raw_user_meta_data,email_confirmed_at)
select ('f1026000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'thanks-'||n||'@test.invalid','authenticated','authenticated','{}','{}',now() from generate_series(1,10)n;
update public.profiles set access_status='active',is_test_account=true,display_name='Amina Tester' where id::text like 'f1026000-%';
insert into public.user_roles(user_id,role,granted_by) values('f1026000-0000-4000-8000-000000000001','super_admin','f1026000-0000-4000-8000-000000000001');
insert into public.venues(id,name,city,country,address_line) values('f1026100-0000-4000-8000-000000000001','[TEST] Thank-you room','Nairobi','Kenya','[TEST] No physical event');
insert into public.events(id,slug,title,format,audience,status,starts_at,ends_at,venue_id,created_by)
values('f1026200-0000-4000-8000-000000000001','test-thank-you','[TEST] Thank-you','in_person','public','published',now()-interval '2 days 3 hours',now()-interval '2 days','f1026100-0000-4000-8000-000000000001','f1026000-0000-4000-8000-000000000001');
insert into public.event_hosts(event_id,user_id,status,assigned_by) values('f1026200-0000-4000-8000-000000000001','f1026000-0000-4000-8000-000000000001','active','f1026000-0000-4000-8000-000000000001');
insert into public.orders(id,user_id,event_id,status,processing_mode,currency,subtotal_minor,total_minor)
select ('f1026300-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('f1026000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
 'f1026200-0000-4000-8000-000000000001',case when n=7 then 'refunded' else 'approved' end,'manual_review','KES',0,0 from generate_series(2,10)n;
insert into public.event_memberships(event_id,user_id,status,order_id)
select 'f1026200-0000-4000-8000-000000000001',('f1026000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
  case when n=5 then 'cancelled' else 'confirmed' end,('f1026300-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(2,10)n;
insert into public.event_checkins(event_id,user_id,method,checked_in_by)
select 'f1026200-0000-4000-8000-000000000001',('f1026000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'manual','f1026000-0000-4000-8000-000000000001' from generate_series(2,10)n where n<>3;
update public.event_checkins set reversed_at=now(),reversed_by=checked_in_by,reversal_reason='[TEST] reversal' where user_id='f1026000-0000-4000-8000-000000000004';
insert into public.notification_preferences(user_id,email_events) values('f1026000-0000-4000-8000-000000000006',false) on conflict(user_id) do update set email_events=false;
update auth.users set email_confirmed_at=null where id='f1026000-0000-4000-8000-000000000008';
update public.profiles set access_status='suspended' where id='f1026000-0000-4000-8000-000000000009';
select pg_temp.thanks_assert(not hat_event_ops.thank_you_eligible('f1026200-0000-4000-8000-000000000001','f1026000-0000-4000-8000-000000000002'),'old event excluded by rollout boundary');
update hat_event_ops.thank_you_release set activated_at=now()-interval '3 days';
select pg_temp.thanks_assert(hat_event_ops.thank_you_due('f1026200-0000-4000-8000-000000000001')=(select (date_trunc('day',ends_at at time zone timezone)+interval '1 day 8 hours') at time zone timezone from public.events where slug='test-thank-you'),'next local morning at eight');
select pg_temp.thanks_assert((select count(*)=2 from public.event_memberships m where m.event_id='f1026200-0000-4000-8000-000000000001' and hat_event_ops.thank_you_eligible(m.event_id,m.user_id)),'only two confirmed checked-in eligible guests');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1026000-0000-4000-8000-000000000002',true);
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.get_event_thank_you_settings('f1026200-0000-4000-8000-000000000001')$q$),'ordinary guest denied settings');
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.queue_due_event_thank_yous('f1026200-0000-4000-8000-000000000001')$q$),'ordinary guest denied queue');
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.get_event_thank_you_email(gen_random_uuid())$q$),'ordinary guest denied email context');
select set_config('request.jwt.claim.sub','f1026000-0000-4000-8000-000000000001',true);
select pg_temp.thanks_assert(public.get_event_thank_you_settings('f1026200-0000-4000-8000-000000000001')->>'enabled'='true','Host default on');
select pg_temp.thanks_assert(public.get_event_thank_you_settings('f1026200-0000-4000-8000-000000000001')->'preview'->>'guest_name'='Amina','preview does not expose guest identity');
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',true,repeat('x',601))$q$),'message limit enforced');
select pg_temp.thanks_assert(public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',false,' Thank you from our Host. ')->>'message'='Thank you from our Host.','Host message trimmed and persisted');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.thanks_assert(public.queue_due_event_thank_yous('f1026200-0000-4000-8000-000000000001')=0,'disabled email queues nobody');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f1026000-0000-4000-8000-000000000001"}',true);
select public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',true,'Thank you from our Host.');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.thanks_assert(public.queue_due_event_thank_yous('f1026200-0000-4000-8000-000000000001')=2,'exactly two jobs queued');
select pg_temp.thanks_assert(public.queue_due_event_thank_yous('f1026200-0000-4000-8000-000000000001')=0,'repeat queue is idempotent');
reset role;
select pg_temp.thanks_assert((select count(*)=2 from hat_event_ops.thank_you_deliveries where event_id='f1026200-0000-4000-8000-000000000001'),'one receipt per eligible guest');
select pg_temp.thanks_assert((select bool_and(j.dedupe_key='event-thank-you:'||d.event_id||':'||d.user_id and j.to_email=u.email) from hat_event_ops.thank_you_deliveries d join public.notification_jobs j on j.id=d.job_id join auth.users u on u.id=d.user_id where d.event_id='f1026200-0000-4000-8000-000000000001'),'correct recipient and dedupe identity');
select set_config('test.thanks.job',(select job_id::text from hat_event_ops.thank_you_deliveries where event_id='f1026200-0000-4000-8000-000000000001' and user_id='f1026000-0000-4000-8000-000000000002'),true);
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f1026000-0000-4000-8000-000000000001"}',true);
select pg_temp.thanks_assert(public.get_event_thank_you_settings('f1026200-0000-4000-8000-000000000001')->>'message_locked'='true','message locks when preparation starts');
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',true,'Changed')$q$),'queued message cannot change');
select public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',false,'Thank you from our Host.');
reset role;
select pg_temp.thanks_assert((select count(*)=2 from public.notification_jobs where dedupe_key like 'event-thank-you:f1026200-%' and status='suppressed'),'switch off stops unclaimed jobs');
set local role authenticated;
select public.save_event_thank_you_settings('f1026200-0000-4000-8000-000000000001',true,'Thank you from our Host.');
reset role;
select pg_temp.thanks_assert((select status='queued' from public.notification_jobs where id=current_setting('test.thanks.job')::uuid),'re-enable resumes same untouched job');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid) is null,'unclaimed job cannot render');
reset role;
update public.notification_jobs set status='processing',locked_at=now(),attempts=1 where id=current_setting('test.thanks.job')::uuid;
set local role service_role;
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->>'guest_name'='Amina','actual claimed guest renders');
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->>'host_message'='Thank you from our Host.','saved message included');
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->>'host_name'='Your event team','unpublished Host identity omitted');
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->>'has_networking'='false','no invented introductions');
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->'community'='null'::jsonb,'no invented Community');
reset role;
update public.profiles set display_name='Different Name' where id='f1026000-0000-4000-8000-000000000002';
set local role service_role;
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid)->>'guest_name'='Amina','retry snapshot stable');
reset role;
insert into public.notification_preferences(user_id,email_events) values('f1026000-0000-4000-8000-000000000002',false) on conflict(user_id) do update set email_events=false;
set local role service_role;
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid) is null,'preference rechecked even after snapshot');
reset role;
update public.notification_preferences set email_events=true where user_id='f1026000-0000-4000-8000-000000000002';
update public.event_checkins set reversed_at=now(),reversed_by=checked_in_by,reversal_reason='[TEST]' where user_id='f1026000-0000-4000-8000-000000000002';
set local role service_role;
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid) is null,'reversed arrival rechecked');
reset role;
update public.event_checkins set reversed_at=null,reversed_by=null,reversal_reason=null where user_id='f1026000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f1026000-0000-4000-8000-000000000001"}',true);
select public.manage_event_lifecycle('f1026200-0000-4000-8000-000000000001','cancel','[TEST] Thank-you cancellation rehearsal','[TEST] This fixture is cancelled inside a rollback-only test.');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.thanks_assert(public.get_event_thank_you_email(current_setting('test.thanks.job')::uuid) is null,'cancelled event rechecked');
reset role;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select set_config('request.jwt.claim.sub','',true);
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.get_event_thank_you_settings('f1026200-0000-4000-8000-000000000001')$q$),'anonymous settings denied');
select pg_temp.thanks_assert(pg_temp.thanks_denied($q$select public.queue_due_event_thank_yous('f1026200-0000-4000-8000-000000000001')$q$),'anonymous queue denied');
reset role;
select pg_temp.thanks_assert(not has_schema_privilege('authenticated','hat_event_ops','usage'),'private delivery records inaccessible');
rollback;
